# Example: Music Library Manager
import requests
import json

# Requirement 7: OOP with Inheritance
class SongCollection:
    def __init__(self, name):
        self.name = name
        self.songs = []

    def add_song(self, song):
        self.songs.append(song)

    def get_count(self):
        return len(self.songs)

class Playlist(SongCollection):
    def __init__(self, name, creator):
        super().__init__(name)
        self.creator = creator

    # Requirement 1: Function with return
    def calculate_average_rating(self):
        if not self.songs:
            return 0
        total = sum(song['rating'] for song in self.songs)
        return total / len(self.songs)

# Requirement 2: Data Structure
my_playlist = Playlist('Favorites', 'User')

# Requirement 3: Data Manipulation
my_playlist.add_song({'title': 'Song 1', 'artist': 'Artist A', 'rating': 5})
my_playlist.add_song({'title': 'Song 2', 'artist': 'Artist B', 'rating': 4})

# Requirement 5: Iteration
for song in my_playlist.songs:
    # Requirement 4: Conditional Logic
    if song['rating'] >= 4:
        print(f"Recommended: {song['title']}")

# Requirement 6: Error Handling
try:
    with open('playlist.json', 'w') as f:
        json.dump(my_playlist.songs, f)
except IOError as e:
    print(f"Error saving playlist: {e}")

# Requirement 8: External Interaction
try:
    response = requests.get('https://api.example.com/songs')
    if response.status_code == 200:
        print('API connected')
except Exception as e:
    print(f"API error: {e}")

