found_function = False
has_return = False
has_parameters = False

for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef):
        # Check if function has parameters (excluding self)
        params = [arg.arg for arg in node.args.args if arg.arg != 'self']
        if len(params) > 0:
            has_parameters = True

        # Check if function has return statement
        for inner in ast.walk(node):
            if isinstance(inner, ast.Return) and inner.value is not None:
                has_return = True
                if has_parameters:
                    found_function = True
                    break

if not found_function:
    if not has_parameters:
        raise AssertionError('Requirement 1: Need at least one function with parameters (other than just self)')
    if not has_return:
        raise AssertionError('Requirement 1: Function must return a value (not just return with no value)')
    raise AssertionError('Requirement 1: Need a function that takes parameters AND returns a value')

