import ast

tree = ast.parse(code)

has_list = False
has_dict = False
has_object = False

for node in ast.walk(tree):
    # Check for list literals
    if isinstance(node, ast.List):
        has_list = True

    # Check for dict literals
    if isinstance(node, ast.Dict):
        has_dict = True

    # Check for class instantiation (creating objects)
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name):
            # Check if calling a class (capitalized name suggests class)
            if node.func.id[0].isupper():
                has_object = True

if not (has_list or has_dict or has_object):
    raise AssertionError('Requirement 2: Need to use data structures - lists [], dictionaries {}, or class objects')

