import ast

tree = ast.parse(code)

manipulation_methods = ['append', 'remove', 'pop', 'insert', 'extend', 'clear', 'update', 'sort', 'reverse', 'add']
found_manipulation = False
has_comprehension = False

for node in ast.walk(tree):
    # Check for method calls that modify data
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if node.func.attr in manipulation_methods:
                found_manipulation = True

    # Check for list/dict comprehensions
    if isinstance(node, (ast.ListComp, ast.DictComp)):
        has_comprehension = True

    # Check for assignment to list/dict elements
    if isinstance(node, ast.Assign):
        for target in node.targets:
            if isinstance(target, ast.Subscript):
                found_manipulation = True

if not (found_manipulation or has_comprehension):
    raise AssertionError('Requirement 3: Need to manipulate data - use .append(), .remove(), .sort(), list comprehensions, or modify dictionary values')

print('TEST_PASSED')

