import ast

tree = ast.parse(code)

classes = []
for node in tree.body:
    if isinstance(node, ast.ClassDef):
        classes.append({
            'name': node.name,
            'bases': [base.id for base in node.bases if isinstance(base, ast.Name)]
        })

if len(classes) < 2:
    raise AssertionError('Requirement 7: Need at least 2 classes - a base class and a child class that inherits from it')

# Check if any class inherits from another
has_inheritance = False
for cls in classes:
    # Check if this class inherits from any other class in the code
    for base in cls['bases']:
        if any(c['name'] == base for c in classes):
            has_inheritance = True
            break

if not has_inheritance:
    raise AssertionError('Requirement 7: Need inheritance - one class should inherit from another using class Child(Parent):')

