import ast

tree = ast.parse(code)

has_import = False
has_file_operation = False
has_api_call = False
has_database = False

for node in ast.walk(tree):
    # Check for relevant imports
    if isinstance(node, ast.Import):
        for alias in node.names:
            if alias.name in ['requests', 'urllib', 'sqlite3', 'psycopg2', 'pymongo', 'json', 'csv']:
                has_import = True

    if isinstance(node, ast.ImportFrom):
        if node.module in ['requests', 'urllib', 'sqlite3', 'psycopg2', 'pymongo']:
            has_import = True

    # Check for file operations
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name):
            if node.func.id == 'open':
                has_file_operation = True

        # Check for API-related method calls
        if isinstance(node.func, ast.Attribute):
            if node.func.attr in ['get', 'post', 'put', 'delete', 'request']:
                has_api_call = True
            if node.func.attr in ['execute', 'commit', 'cursor', 'connect']:
                has_database = True

if not (has_import and (has_file_operation or has_api_call or has_database)):
    if not has_import:
        raise AssertionError('Requirement 8: Need to import a library for external interaction (requests, sqlite3, json, csv, etc.)')
    raise AssertionError('Requirement 8: Need external interaction code - API call (requests.get), file operation (open), or database query')

